import '../database/enums.dart';

// The food catalog: entirely the user's own product list (see
// project memory / conversation history for provenance) — no generic
// curated starter set and no Open Food Facts / Mercadona branded import
// remain, by explicit request. All values per 100g. Synced into the local
// database on every launch by food_seeder.dart (entries missing by name are
// inserted, existing ones updated in place, and anything no longer in this
// list is deleted) — the app never depends on this list, or on any network
// call, at runtime otherwise. Users extend it freely via "Crear alimento
// personalizado" (isCustom = true on those rows, never touched by the sync).
class FoodSeed {
  const FoodSeed({
    required this.category,
    required this.name,
    required this.kcalPer100g,
    required this.proteinPer100g,
    required this.carbsPer100g,
    required this.fatPer100g,
    this.fiberPer100g,
    this.defaultServingGrams,
    this.servingLabel,
  });

  final FoodCategory category;
  final String name;
  final double kcalPer100g;
  final double proteinPer100g;
  final double carbsPer100g;
  final double fatPer100g;
  final double? fiberPer100g;
  final double? defaultServingGrams;
  final String? servingLabel;
}

